/* Custom Animations */
@keyframes pulse-slow {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.8; transform: scale(1.02); }
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(-10px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes bounce {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-5px); }
}

@keyframes spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@keyframes pulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.1); }
}

@keyframes shake {
  0%, 100% { transform: rotate(0deg); }
  25% { transform: rotate(-10deg); }
  75% { transform: rotate(10deg); }
}

@keyframes flicker {
  0% { opacity: 1; }
  100% { opacity: 0.7; }
}

/* Utility Classes */
.animate-pulse-slow {
  animation: pulse-slow 3s ease-in-out infinite;
}

.animate-fadeIn {
  animation: fadeIn 0.2s ease-out;
}

/* Component Styles */
.btn-primary {
  @apply bg-gradient-to-r from-emerald-600 to-green-600 hover:from-emerald-700 hover:to-green-700 text-white font-semibold px-6 py-3 rounded-full transition-all duration-300 hover:scale-105 shadow-lg hover:shadow-xl;
}

.btn-secondary {
  @apply bg-white border-2 border-emerald-600 text-emerald-600 hover:bg-emerald-50 font-semibold px-6 py-3 rounded-full transition-colors duration-300;
}

.card {
  @apply bg-white rounded-2xl shadow-lg p-6;
}

.weed-card {
  @apply transition-all duration-300 hover:transform hover:scale-[1.02];
}

.tab-active {
  @apply border-emerald-600 text-emerald-700;
}

.option-btn:hover:not(:disabled) {
  @apply transform scale-[1.02];
}

.line-clamp-2 {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* Quiz Category Hover Animations */
.quiz-category:hover .fa-search { animation: bounce 0.5s; }
.quiz-category:hover .fa-utensils { animation: spin 0.5s; }
.quiz-category:hover .fa-heart { animation: pulse 0.5s; }
.quiz-category:hover .fa-skull-crossbones { animation: shake 0.5s; }
.quiz-category:hover .fa-exclamation-triangle { animation: shake 0.5s ease-in-out; }
.quiz-category:hover .fa-mountain { animation: bounce 1s infinite; }
.quiz-category:hover .fa-fire { animation: flicker 0.5s infinite alternate; }

/* Custom Scrollbar for thumbnail strip */
.thumbnail-strip::-webkit-scrollbar {
  height: 6px;
}

.thumbnail-strip::-webkit-scrollbar-track {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 3px;
}

.thumbnail-strip::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.3);
  border-radius: 3px;
}

.thumbnail-strip::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.5);
}

/* Global scrollbar */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  @apply bg-gray-100 rounded-full;
}

::-webkit-scrollbar-thumb {
  @apply bg-emerald-400 rounded-full hover:bg-emerald-500 transition-colors;
}

/* Glassmorphism Effects */
.glass-card {
  @apply bg-white/10 backdrop-blur-sm border border-white/20;
}

/* Smooth Transitions */
* {
  transition: background-color 0.2s ease, border-color 0.2s ease;
}

/* Mobile Optimizations */
@media (max-width: 640px) {
  .quiz-category {
    @apply p-4;
  }

  .btn-primary, .btn-secondary {
    @apply px-4 py-2 text-sm;
  }

  .weed-card .emoji-icon {
    @apply text-5xl;
  }

  .thumbnail-strip {
    padding: 0 8px;
  }

  .thumbnail-strip button {
    @apply w-12 h-12;
  }
}

/* Print Styles */
@media print {
  .btn-primary, .btn-secondary, button {
    @apply hidden;
  }
}

/* Image loading state */
.image-placeholder {
  background: linear-gradient(45deg, #f0f0f0 25%, #e0e0e0 25%, #e0e0e0 50%, #f0f0f0 50%, #f0f0f0 75%, #e0e0e0 75%, #e0e0e0);
  background-size: 40px 40px;
  animation: loading 1s linear infinite;
}

@keyframes loading {
  0% { background-position: 0 0; }
  100% { background-position: 40px 40px; }
}
